import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

final class KruskalMST {
    private KruskalMST() {
    }

    public static int kruskalsMST(int vertexCount, int[][] rawEdges) {
        return minimumSpanningTree(vertexCount, rawEdges).totalWeight();
    }

    public static int kruskalsMST(int vertexCount, Edge[] edges) {
        return minimumSpanningTree(vertexCount, edges).totalWeight();
    }

    public static MstResult minimumSpanningTree(int vertexCount, int[][] rawEdges) {
        return minimumSpanningTree(WeightedGraph.of(vertexCount, rawEdges));
    }

    public static MstResult minimumSpanningTree(int vertexCount, Edge[] edges) {
        return minimumSpanningTree(WeightedGraph.of(vertexCount, edges));
    }

    public static MstResult minimumSpanningTree(WeightedGraph graph) {
        List<Edge> sortedEdges = new ArrayList<>(graph.edges());
        sortedEdges.sort(Comparator.comparingInt(Edge::weight));

        DisjointSet disjointSet = new DisjointSet(graph.vertexCount());
        List<Edge> selectedEdges = new ArrayList<>(Math.max(0, graph.vertexCount() - 1));
        int totalWeight = 0;

        for (Edge edge : sortedEdges) {
            if (disjointSet.union(edge.from(), edge.to())) {
                selectedEdges.add(edge);
                totalWeight += edge.weight();
                if (selectedEdges.size() == graph.vertexCount() - 1) {
                    break;
                }
            }
        }
        return new MstResult(
            totalWeight,
            selectedEdges,
            selectedEdges.size() == graph.vertexCount() - 1
        );
    }

    public static void main(String[] args) {
        Edge[] edges = {
            new Edge(0, 1, 10),
            new Edge(1, 3, 15),
            new Edge(2, 3, 4),
            new Edge(2, 0, 6),
            new Edge(0, 3, 5)
        };

        System.out.println(kruskalsMST(4, edges));
    }
}

